    .activity-home-top { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px dashed #e2e8f0; padding-bottom: 10px; margin-bottom: 12px; }
    .activity-home-badge { font-size: 0.8rem; font-weight: 700; color: #475569; }
