    .activity-home-title { font-size: 1.05rem; font-weight: 800; color: #0f172a; margin-bottom: 14px; line-height: 1.6; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
