        .btn-download-form { width: 100%; justify-content: center; }
        .golden-text-3d { font-size: 1.8rem; }
        .awqaf-sidebar-toggle-bar { top: 15px; right: 15px; scale: 0.9; }
        .sidebar-open .awqaf-sidebar-toggle-bar { right: 15px; }
    }
</style>

<script>
document.addEventListener('DOMContentLoaded', function () {
