{#
    ==========================================================================
    صفحة: الأنشطة والفعاليات (active-taq-web) - منصة سبيل الرشاد
    التصميم: الهوية البصرية التحريرية (لودن/براص/ذهبي) + خطوط Amiri/Tajawal
    الوظائف: جلب حقيقي من Frappe، فلترة ذكية، تصويت عبر API، بث مباشر
    ==========================================================================
#}

{% set activities = frappe.get_all("active_taq",
    fields=["name", "en", "ty", "assignment_type", "naa", "da", "mak", "route", "locc", "significant_event", "live_stream_url"],
    filters={"docstatus": 0, "workflow_state_wa": "تكليف معتمد"},
    order_by="significant_event desc, da desc") %}

{# قراءة خيارات حقل are_you ديناميكياً من تعريف الحقل #}
{% set are_you_field_meta = frappe.get_meta("active_taq").get_field("are_you") %}
{% set are_you_raw_options = are_you_field_meta.options if are_you_field_meta and are_you_field_meta.options else "" %}
{% set are_you_options = [] %}
{% for o in are_you_raw_options.split("\n") %}
    {% if o.strip() %}
        {% set _ = are_you_options.append(o.strip()) %}
    {% endif %}
{% endfor %}

<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Amiri:ital,wght@0,400;0,700;1,400&family=Tajawal:wght@300;400;500;700;900&display=swap" rel="stylesheet">
<script src="https://unpkg.com/lucide@latest"></script>

<style>
    :root {
        --loden: #1d3028;
        --loden-dark: #13221c;
        --loden-light: #2a4439;
        --brass: #b59a62;
        --brass-light: #caba94;
        --gold: #d1bb86;
        --paper: #f1eee6;
        --paper-card: #e8e4d8;
        --text-dark: #1a1a1a;
        --text-muted: #5a6560;
        --sidebar-width: 280px;
        --filter-width: 340px;
    }

    .sabeel-page-wrapper * {
        box-sizing: border-box;
    }

    .sabeel-page-wrapper {
        font-family: 'Tajawal', sans-serif;
        background-color: var(--paper);
        color: var(--text-dark);
        line-height: 1.6;
        overflow-x: hidden;
        position: relative;
        width: 100%;
    }

    .sabeel-page-wrapper h1,
    .sabeel-page-wrapper h2,
    .sabeel-page-wrapper h3,
    .sabeel-page-wrapper h4,
    .sabeel-page-wrapper .font-serif {
        font-family: 'Amiri', serif;
    }

    /* ===================== Sidebar (Main Nav) ===================== */
    .sidebar-backdrop {
        position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
        background: rgba(19, 34, 28, 0.5); backdrop-filter: blur(4px);
        z-index: 990; opacity: 0; pointer-events: none; transition: opacity 0.3s ease;
    }
    .sidebar-backdrop.active { opacity: 1; pointer-events: auto; }

    .sidebar {
        position: fixed; top: 0; right: calc(-1 * var(--sidebar-width));
        width: var(--sidebar-width); height: 100vh;
        background: rgba(29, 48, 40, 0.9); backdrop-filter: blur(16px);
        border-left: 1px solid rgba(181, 154, 98, 0.2);
        z-index: 1000; display: flex; flex-direction: column;
        transition: right 0.3s cubic-bezier(0.4, 0, 0.2, 1); color: var(--paper);
    }
    .sidebar.open { right: 0; }
    .sidebar-header {
        padding: 2rem 1.5rem 1rem; display: flex; justify-content: space-between;
        align-items: center; border-bottom: 1px solid rgba(181, 154, 98, 0.15);
    }
    .sidebar-title { color: var(--gold); font-size: 1.35rem; font-weight: 700; }
    .close-sidebar-btn {
        background: transparent; border: none; color: var(--paper); cursor: pointer;
        padding: 0.5rem; border-radius: 50%; display: flex; align-items: center;
        justify-content: center; transition: background 0.2s;
    }
    .close-sidebar-btn:hover { background: rgba(181, 154, 98, 0.2); color: var(--gold); }
    .sidebar-menu { list-style: none; padding: 1.5rem 0; margin: 0; flex: 1; overflow-y: auto; }
    .sidebar-menu-item a {
        display: flex; align-items: center; gap: 1rem; padding: 1rem 1.5rem;
        color: var(--paper); text-decoration: none; font-size: 1.05rem;
        transition: all 0.2s; border-right: 3px solid transparent;
    }
    .sidebar-menu-item a:hover,
    .sidebar-menu-item a.active {
        background: rgba(181, 154, 98, 0.15); color: var(--gold); border-right-color: var(--gold);
    }
    .sidebar-footer { padding: 1rem 1.5rem; text-align: center; color: rgba(241,238,230,0.5); font-size: 0.8rem; border-top: 1px solid rgba(181,154,98,0.15); }

    /* ===================== Top Header Frame ===================== */
    .top-frame {
        position: sticky; top: 0; z-index: 100; background: var(--loden);
        border-bottom: 2px solid var(--brass); padding: 0.75rem 2rem;
        display: flex; justify-content: space-between; align-items: center;
        box-shadow: 0 4px 20px rgba(0,0,0,0.15);
    }
    /* زر القائمة أولاً بالترتيب => يظهر من اليمين في RTL */
    .nav-toggle-btn {
        order: 1;
        background: rgba(181, 154, 98, 0.15); border: 1px solid var(--brass); color: var(--gold);
        padding: 0.5rem 1rem; border-radius: 4px; cursor: pointer; display: flex;
        align-items: center; gap: 0.5rem; font-family: 'Tajawal', sans-serif;
        font-weight: 500; transition: all 0.2s;
    }
    .nav-toggle-btn:hover { background: var(--brass); color: var(--loden-dark); }
    .brand-logo {
        order: 2;
        color: var(--paper); font-size: 1.3rem; font-weight: 700; text-decoration: none;
        display: flex; align-items: center; gap: 0.5rem;
    }
    .brand-logo span { color: var(--gold); }

    /* ===================== Hero Section ===================== */
    .hero-section {
        position: relative; height: 62vh; min-height: 480px; max-height: 680px;
        background: linear-gradient(180deg, rgba(29, 48, 40, 0.45) 0%, rgba(29, 48, 40, 0.55) 55%, rgba(19, 34, 28, 0.9) 100%),
                    url('/files/Gemini_Generated_Image_vxorplvxorplvxor.jpg') center 30%/cover no-repeat;
        display: flex; align-items: center; justify-content: center; text-align: center;
        color: var(--paper); padding: 0 1rem; border-bottom: 1px solid var(--brass);
    }
    .hero-content { max-width: 800px; }
    .kicker {
        color: var(--gold); font-size: 0.95rem; letter-spacing: 2px; text-transform: uppercase;
        margin-bottom: 0.5rem; font-weight: 700;
    }
    .hero-title { font-size: 2.6rem; font-weight: 700; margin-bottom: 1rem; color: var(--paper); line-height: 1.3; }
    .hero-subtitle { font-size: 1.1rem; color: rgba(241, 238, 230, 0.85); font-weight: 300; }

    /* ===================== Container ===================== */
    .sabeel-container { max-width: 1200px; margin: 0 auto; padding: 3rem 1.5rem; }
    .editorial-header {
        margin-bottom: 2rem; display: flex; justify-content: space-between; align-items: flex-end;
        border-bottom: 1px solid rgba(181, 154, 98, 0.3); padding-bottom: 1rem; flex-wrap: wrap; gap: 1rem;
    }
    .section-no { font-family: 'Amiri', serif; font-size: 1.2rem; color: var(--brass); font-style: italic; }

    .quick-filters { display: flex; gap: 0.5rem; flex-wrap: wrap; }
    .quick-filter-btn {
        background: transparent; border: 1px solid var(--loden); color: var(--loden);
        padding: 0.5rem 1.1rem; border-radius: 30px; cursor: pointer; font-family: 'Tajawal', sans-serif;
        font-weight: 500; font-size: 0.88rem; transition: all 0.2s; white-space: nowrap;
    }
    .quick-filter-btn:hover { background: rgba(29,48,40,0.08); }
    .quick-filter-btn.active { background: var(--loden); color: var(--paper); border-color: var(--loden); }

    /* ===================== Filter Trigger + Advanced Panel ===================== */
    .filter-trigger-wrapper { margin-bottom: 2rem; }
    .btn-filter-trigger {
        background: var(--loden); color: var(--gold) !important; border: 1px solid var(--brass);
        padding: 0.65rem 1.4rem; border-radius: 30px; font-weight: 700; font-size: 0.9rem;
        cursor: pointer; display: inline-flex; align-items: center; gap: 8px;
        box-shadow: 0 6px 16px rgba(0,0,0,0.15); transition: all 0.2s;
    }
    .btn-filter-trigger:hover { background: var(--brass); color: var(--loden-dark) !important; }

    .filter-panel {
        position: fixed; top: 0; left: calc(-1 * var(--filter-width)); width: var(--filter-width);
        height: 100vh; background: var(--loden-dark); border-right: 2px solid var(--brass);
        z-index: 1300; display: flex; flex-direction: column; transition: left 0.35s ease;
        color: var(--paper);
    }
    .filter-panel.open { left: 0; }
    .filter-panel-header {
        padding: 1.5rem; background: var(--loden); border-bottom: 1px solid rgba(181,154,98,0.3);
        display: flex; justify-content: space-between; align-items: center;
    }
    .filter-panel-header h3 { color: var(--gold); font-size: 1.15rem; margin: 0; display: flex; align-items: center; gap: 8px; }
    .filter-panel-body { padding: 1.5rem; overflow-y: auto; flex: 1; }
    .filter-group { margin-bottom: 1.25rem; position: relative; }
    .filter-label {
        font-size: 0.8rem; color: var(--brass-light); font-weight: 600; margin-bottom: 6px;
        display: flex; align-items: center; gap: 6px;
    }
    .filter-input {
        width: 100%; background: var(--paper) !important; border: 1px solid var(--brass) !important;
        color: var(--text-dark) !important; font-family: 'Tajawal', sans-serif; font-size: 0.88rem;
        font-weight: 500; height: 40px; border-radius: 5px; padding: 0 12px; outline: none;
    }
    .filter-input:focus { border-color: var(--gold) !important; }
    .autocomplete-suggestions {
        position: absolute; top: 100%; left: 0; right: 0; background: #ffffff; color: var(--text-dark);
        border: 1px solid var(--brass); border-radius: 0 0 6px 6px; max-height: 200px; overflow-y: auto;
        z-index: 9999; display: none; box-shadow: 0 8px 16px rgba(0,0,0,0.3);
    }
    .suggestion-item { padding: 9px 14px; cursor: pointer; font-size: 0.85rem; font-weight: 600; text-align: right; border-bottom: 1px solid #f1f5f9; }
    .suggestion-item:hover { background: var(--paper-card); }
