    .card-top-row {
        display: flex; align-items: center; justify-content: space-between; gap: 0.5rem;
        padding: 1rem 1.75rem 0;
    }
    .card-badge {
        background: var(--loden); color: var(--gold);
        padding: 0.25rem 0.75rem; font-size: 0.8rem; border-radius: 4px; border: 1px solid var(--brass);
        font-weight: 500; white-space: nowrap;
    }
    .card-pin-badge {
        background: linear-gradient(135deg, var(--brass) 0%, var(--gold) 100%);
        color: var(--loden-dark); padding: 0.25rem 0.65rem; font-size: 0.75rem; font-weight: 800;
        border-radius: 4px; display: flex; align-items: center; gap: 4px; white-space: nowrap;
    }
    .card-pin-badge i { transform: rotate(45deg); width: 12px; height: 12px; }

    .card-body { padding: 1.25rem 1.75rem 1.75rem; display: flex; flex-direction: column; flex: 1; }
    .card-kicker { font-size: 0.85rem; color: var(--brass); font-weight: 700; margin-bottom: 0.25rem; }
    .card-title { font-size: 1.35rem; color: var(--loden-dark); margin-bottom: 1rem; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
    .card-meta { display: flex; flex-direction: column; gap: 0.5rem; margin-bottom: 1.5rem; color: var(--text-muted); font-size: 0.92rem; }
    .meta-item { display: flex; align-items: center; gap: 0.5rem; }
    .meta-item i { width: 16px; height: 16px; flex-shrink: 0; color: var(--brass); }
    .meta-preachers { display: flex; flex-direction: column; gap: 4px; }
    .meta-preachers span { font-weight: 700; color: var(--loden-dark); }

    .card-footer { margin-top: auto; padding-top: 1rem; border-top: 1px dashed rgba(181, 154, 98, 0.3); display: flex; gap: 0.6rem; flex-wrap: wrap; }
    .btn { padding: 0.6rem 1rem; border-radius: 4px; font-family: 'Tajawal', sans-serif; font-size: 0.92rem; font-weight: 500; cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; justify-content: center; gap: 0.4rem; transition: all 0.2s; border: none; }
    .btn-primary { background: var(--loden); color: var(--paper); flex: 1; }
    .btn-primary:hover { background: var(--loden-light); }
    .btn-secondary { background: transparent; border: 1px solid var(--brass); color: var(--loden-dark); }
    .btn-secondary:hover { background: rgba(181, 154, 98, 0.15); }
    .btn-live { background: #a83232; color: #ffffff !important; animation: pulse 2s infinite; text-decoration: none; }
    .btn-live:hover { background: #922b2b; }
    @keyframes pulse { 0% { box-shadow: 0 0 0 0 rgba(168, 50, 50, 0.4); } 70% { box-shadow: 0 0 0 8px rgba(168, 50, 50, 0); } 100% { box-shadow: 0 0 0 0 rgba(168, 50, 50, 0); } }

    .empty-state { grid-column: 1 / -1; text-align: center; padding: 4rem 1rem; border: 2px dashed rgba(29,48,40,0.15); border-radius: 10px; color: var(--text-muted); }

    /* ===================== Modal Popup ===================== */
    .modal-overlay {
        position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: rgba(19, 34, 28, 0.7);
        backdrop-filter: blur(6px); z-index: 2000; display: flex; align-items: center; justify-content: center;
        opacity: 0; pointer-events: none; transition: opacity 0.3s; padding: 1rem;
    }
    .modal-overlay.active { opacity: 1; pointer-events: auto; }
    .modal-card { background: var(--paper); border: 2px solid var(--brass); width: 100%; max-width: 700px; border-radius: 8px; box-shadow: 0 20px 40px rgba(0,0,0,0.3); max-height: 90vh; overflow-y: auto; position: relative; }
    .modal-header { background: var(--loden); color: var(--paper); padding: 1.5rem; display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--brass); gap: 1rem; }
    .modal-title { color: var(--gold); font-size: 1.4rem; }
    .modal-subtitle { font-size: 0.78rem; color: rgba(241,238,230,0.65); display: block; margin-top: 4px; }
    .modal-body { padding: 1.5rem; }

    .meta-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 1rem; margin-bottom: 1.5rem; }
    .meta-tile { background: var(--paper-card); border: 1px solid rgba(181,154,98,0.3); border-bottom: 3px solid var(--loden); border-radius: 8px; padding: 0.9rem 1rem; display: flex; align-items: center; gap: 0.7rem; }
    .meta-tile i { color: var(--loden); flex-shrink: 0; }
    .meta-tile-content { display: flex; flex-direction: column; }
    .meta-tile-label { font-size: 0.72rem; color: var(--text-muted); font-weight: 700; }
    .meta-tile-value { font-size: 0.95rem; font-weight: 800; color: var(--loden-dark); }

    .section-divider { display: flex; align-items: center; gap: 8px; margin: 1.5rem 0 0.75rem; font-weight: 800; color: var(--loden-dark); font-size: 1rem; border-bottom: 1px solid rgba(181,154,98,0.3); padding-bottom: 0.5rem; }
    .section-divider i { color: var(--brass); }

    .speakers-table { width: 100%; border-collapse: collapse; margin: 0.5rem 0 1rem; font-size: 0.92rem; }
    .speakers-table th, .speakers-table td { padding: 0.7rem 0.9rem; text-align: right; border-bottom: 1px solid rgba(181, 154, 98, 0.2); }
    .speakers-table th { background: rgba(181, 154, 98, 0.15); color: var(--loden-dark); font-weight: 700; }
    .speakers-table td strong { color: var(--loden-dark); }

    .route-box { background: var(--paper-card); border: 1px solid rgba(181,154,98,0.3); border-right: 4px solid var(--brass); padding: 1rem; border-radius: 6px; font-size: 0.9rem; color: var(--text-dark); line-height: 1.8; }

    .interest-box { background: var(--paper-card); border: 1px solid rgba(181, 154, 98, 0.3); padding: 1rem; border-radius: 6px; margin-top: 1.5rem; }
    .interest-box-title { font-weight: 700; color: var(--loden-dark); display: flex; align-items: center; gap: 6px; margin-bottom: 0.9rem; }
    .are-you-options-box { display: flex; gap: 10px; flex-wrap: wrap; }
    .btn-are-you { background: #ffffff; border: 2px solid var(--brass-light); color: var(--text-dark); padding: 8px 22px; border-radius: 30px; font-weight: 700; font-size: 0.88rem; cursor: pointer; transition: all 0.2s ease; font-family: 'Tajawal', sans-serif; }
    .btn-are-you:hover { border-color: var(--brass); color: var(--loden-dark); }
    .btn-are-you.selected { background: linear-gradient(135deg, var(--brass) 0%, var(--gold) 100%); border-color: var(--brass); color: var(--loden-dark); }
    .btn-are-you.locked { opacity: 0.55; cursor: not-allowed; pointer-events: none; }
    .are-you-feedback { margin-top: 0.8rem; padding: 0.6rem 0.9rem; border-radius: 6px; font-size: 0.85rem; font-weight: 700; background-color: #dcfce7; color: #15803d; border: 1px solid #bbf7d0; display: flex; align-items: center; gap: 6px; }
    .are-you-feedback.failed { background-color: #fee2e2; color: #b91c1c; border: 1px solid #fecaca; }
    .are-you-feedback.hidden { display: none; }

    .modal-footer-actions { display: flex; justify-content: space-between; align-items: center; padding: 1rem 1.5rem 1.5rem; gap: 1rem; flex-wrap: wrap; }
    .btn-map-link { background-color: var(--loden); color: #fff !important; border: none; padding: 0.6rem 1.1rem; border-radius: 6px; font-weight: 700; font-size: 0.85rem; display: inline-flex; align-items: center; gap: 6px; text-decoration: none !important; }
    .btn-map-link:hover { background-color: var(--brass); color: #fff !important; }

    /* ===================== Responsive ===================== */
    @media (max-width: 768px) {
        .hero-section { height: 46vh; min-height: 340px; }
        .hero-title { font-size: 1.9rem; }
        .top-frame { padding: 0.65rem 1rem; }
        .brand-logo { font-size: 1.05rem; }
    }
</style>

<div class="sabeel-page-wrapper" id="sabeelPageWrapper" dir="rtl">

    <!-- Backdrop & Sidebar (Main Nav) -->
    <div class="sidebar-backdrop" id="sidebarBackdrop"></div>
    <aside class="sidebar" id="mainSidebar">
        <div class="sidebar-header">
            <h2 class="sidebar-title font-serif">منصة سبيل الرشاد</h2>
            <button class="close-sidebar-btn" id="closeMainSidebar"><i data-lucide="x"></i></button>
        </div>
        <ul class="sidebar-menu">
            <li class="sidebar-menu-item"><a href="/home"><i data-lucide="home"></i> الرئيسية</a></li>
            <li class="sidebar-menu-item"><a href="/active-taq-web" class="active"><i data-lucide="calendar-days"></i> الأنشطة والفعاليات</a></li>
            <li class="sidebar-menu-item"><a href="/album-photo"><i data-lucide="image"></i> ألبوم الصور</a></li>
            <li class="sidebar-menu-item"><a href="/about-us"><i data-lucide="landmark"></i> حول الإدارة</a></li>
            <li class="sidebar-menu-item"><a href="/call-us"><i data-lucide="mail"></i> اتصل بنا</a></li>
        </ul>
        <div class="sidebar-footer">© منصة سبيل الرشاد</div>
    </aside>

    <!-- Header Navigation Frame -->
    <header class="top-frame">
        <button class="nav-toggle-btn" id="openMainSidebar">
            <i data-lucide="menu"></i> القائمة
        </button>
        <a href="/home" class="brand-logo font-serif">
            <i data-lucide="book-open" style="color: var(--gold);"></i>
            منصة <span>سبيل الرشاد</span>
        </a>
    </header>

    <!-- Hero Section -->
    <section class="hero-section">
        <div class="hero-content">
            <div class="kicker">جدول البرامج والدورات</div>
            <h1 class="hero-title font-serif">الأنشطة الدعوية والملتقيات العلمية</h1>
            <p class="hero-subtitle">تحت إشراف إدارة الشؤون الثقافية والدعوية - منصة سبيل الرشاد</p>
        </div>
    </section>

    <!-- Main Container -->
    <main class="sabeel-container">

        <div class="editorial-header">
            <div>
                <span class="section-no">قسم ٠٢</span>
                <h2 style="font-size: 1.9rem; color: var(--loden-dark);">دليل الفعاليات</h2>
            </div>
            <div class="quick-filters" id="quickFilters"></div>
        </div>

        <!-- Filter Trigger -->
        <div class="filter-trigger-wrapper">
            <button type="button" class="btn-filter-trigger" id="openFilterPanelBtn">
                <i data-lucide="sliders-horizontal"></i>
                <span>فلترة البحث المتقدمة</span>
            </button>
        </div>

        <!-- Advanced Filter Panel -->
        <div class="filter-panel-overlay" id="filterPanelOverlay"></div>
        <div class="filter-panel" id="filterPanel">
            <div class="filter-panel-header">
                <h3><i data-lucide="filter"></i> خيارات الفلترة الذكية</h3>
                <button type="button" class="close-sidebar-btn" id="closeFilterPanelBtn"><i data-lucide="x"></i></button>
            </div>
            <div class="filter-panel-body">

                <div class="filter-group">
                    <label class="filter-label"><i data-lucide="user" style="width:14px;height:14px;color:var(--brass);"></i> اسم الشيخ / الوعاظ</label>
                    <input type="text" id="searchByPreacher" class="filter-input autocomplete-input" placeholder="ابحث باسم الشيخ..." autocomplete="off">
                    <div class="autocomplete-suggestions" id="preacherSuggestions"></div>
                </div>

                <div class="filter-group">
                    <label class="filter-label"><i data-lucide="layers" style="width:14px;height:14px;color:var(--brass);"></i> الجانب الدعوي</label>
                    <input type="text" id="searchByAspect" class="filter-input autocomplete-input" placeholder="ابحث باسم الجانب..." autocomplete="off">
                    <div class="autocomplete-suggestions" id="aspectSuggestions"></div>
                </div>

                <div class="filter-group">
                    <label class="filter-label"><i data-lucide="heading" style="width:14px;height:14px;color:var(--brass);"></i> عنوان النشاط</label>
                    <input type="text" id="searchByTitle" class="filter-input autocomplete-input" placeholder="ابحث عن عنوان الدرس..." autocomplete="off">
                    <div class="autocomplete-suggestions" id="titleSuggestions"></div>
                </div>

                <div class="filter-group">
                    <label class="filter-label"><i data-lucide="book-open" style="width:14px;height:14px;color:var(--brass);"></i> نوع المنشط العلمي</label>
                    <input type="text" id="searchByType" class="filter-input autocomplete-input" placeholder="محاضرة، دورة، ندوة..." autocomplete="off">
                    <div class="autocomplete-suggestions" id="typeSuggestions"></div>
                </div>

                <div class="filter-group">
                    <label class="filter-label"><i data-lucide="landmark" style="width:14px;height:14px;color:var(--brass);"></i> المكتب الإداري</label>
                    <input type="text" id="searchByOffice" class="filter-input autocomplete-input" placeholder="ابحث عن المكتب الإداري..." autocomplete="off">
                    <div class="autocomplete-suggestions" id="officeSuggestions"></div>
                </div>

                <div class="filter-group">
                    <label class="filter-label"><i data-lucide="calendar" style="width:14px;height:14px;color:var(--brass);"></i> التاريخ المحدّد</label>
                    <input type="date" id="searchByDate" class="filter-input">
                </div>

                <button type="button" class="btn-reset-filters" id="resetFiltersBtn">
                    <i data-lucide="rotate-ccw"></i> إعادة تعيين الفلاتر
                </button>
            </div>
        </div>

        <!-- Activities Grid -->
        <div class="activities-grid" id="activitiesGrid">
            {% if activities %}
                {% for act in activities %}

                    {% set child_preachers = frappe.get_all("Active Taq Preachers", filters={"parent": act.name}, fields=["preacher", "title", "lecture_time", "lecture_duration"]) %}
                    {% set preacher_clean_names = [] %}
                    {% set json_preachers_data = [] %}
                    {% set backup_titles = [] %}

                    {% for p in child_preachers %}
                        {% if p.preacher %}
                            {% set p_info = frappe.db.get_value("waed_info", p.preacher, "namee") %}
                            {% if p_info %}
                                {% set _ = preacher_clean_names.append("فضيلة الشيخ " ~ p_info) %}
                                {% set active_lesson = p.title if p.title else "" %}
                                {% if active_lesson %}
                                    {% set _ = backup_titles.append(active_lesson) %}
                                {% endif %}
                                {% set _ = json_preachers_data.append({
                                    "name": "فضيلة الشيخ " ~ p_info,
                                    "lesson": active_lesson or act.en or "تابع للملتقى العلمي",
                                    "lecture_time": p.lecture_time or "-",
                                    "lecture_duration": p.lecture_duration or "-"
                                }) %}
                            {% endif %}
                        {% endif %}
                    {% endfor %}

                    {% if act.naa %}
                        {% set single_p_info = frappe.db.get_value("waed_info", act.naa, "namee") %}
                        {% if single_p_info %}
                            {% set _ = preacher_clean_names.append("فضيلة الشيخ " ~ single_p_info) %}
                        {% endif %}
                    {% endif %}

                    {% set fallback_title = backup_titles | join(" و ") if backup_titles else "نشاط دعوي وعلمي" %}
                    {% set final_display_title = act.en or fallback_title %}
                    {% set all_preachers_string = preacher_clean_names | join(" ، ") %}
                    {% set json_string_data = json_preachers_data | tojson | forceescape %}

                    <article class="activity-card {{ 'significant' if act.significant_event else '' }}"
                        data-preacher="{{ all_preachers_string or 'نخبة من الوعاظ الفضلاء' }}"
                        data-aspect="{{ act.assignment_type or 'عام' }}"
                        data-title="{{ final_display_title }}"
                        data-type="{{ act.ty or '' }}"
                        data-office="{{ act.mak or '' }}"
                        data-date="{{ act.da or '' }}">

                        <div class="card-top-row">
                            <span class="card-badge">{{ act.ty or "نشاط عام" }}</span>
                            {% if act.significant_event %}
                                <span class="card-pin-badge"><i data-lucide="pin"></i> حدث مهم</span>
                            {% endif %}
                        </div>

                        <div class="card-body">
                            <span class="card-kicker">{{ act.assignment_type or "تكليف عام" }}</span>
                            <h3 class="card-title font-serif">{{ final_display_title }}</h3>

                            <div class="card-meta">
                                <div class="meta-preachers">
                                    {% if preacher_clean_names %}
                                        {% for p_name in preacher_clean_names %}
                                            <span><i data-lucide="user" style="display:inline-block;width:14px;height:14px;vertical-align:-2px;color:var(--brass);"></i> {{ p_name }}</span>
                                        {% endfor %}
                                    {% else %}
                                        <span>نخبة من الوعاظ الفضلاء</span>
                                    {% endif %}
                                </div>
                                <div class="meta-item"><i data-lucide="calendar-days"></i> {{ act.da or "قريباً" }}</div>
                                <div class="meta-item"><i data-lucide="landmark"></i> {{ act.mak or "المكتب الإداري" }}</div>
                            </div>

                            <div class="card-footer">
                                <button class="btn btn-primary btn-details"
                                        data-title="{{ final_display_title }}"
                                        data-type="{{ act.ty or 'نشاط عام' }}"
                                        data-office="{{ act.mak or 'غير محدد' }}"
                                        data-assignment="{{ act.assignment_type or 'غير محدد' }}"
                                        data-preachers-json="{{ json_string_data }}"
                                        data-date="{{ act.da or 'غير محدد' }}"
                                        data-route="{{ act.route or 'لا يوجد مسار مسجل حالياً' }}"
                                        data-activity-id="{{ act.name }}">
                                    <i data-lucide="info"></i> التفاصيل
                                </button>
                                <a href="/activity-location?id={{ act.name }}" class="btn btn-secondary"><i data-lucide="navigation"></i></a>
                                {% if act.live_stream_url %}
                                <a href="{{ act.live_stream_url }}" target="_blank" rel="noopener" class="btn btn-live" title="بث مباشر"><i data-lucide="radio"></i></a>
                                {% endif %}
                            </div>
                        </div>
                    </article>
                {% endfor %}
            {% else %}
                <div class="empty-state">
                    <i data-lucide="clipboard-list" style="width:36px;height:36px;margin-bottom:0.75rem;"></i>
                    <h5>لا توجد مناشط أو لقاءات علمية معتمدة حالياً.</h5>
                </div>
            {% endif %}
        </div>
    </main>

    <!-- Modal Popup for Activity Details -->
    <div class="modal-overlay" id="activityModal">
        <div class="modal-card">
            <div class="modal-header">
                <div>
                    <h3 class="modal-title font-serif" id="modalActivityTitle">--</h3>
                    <span class="modal-subtitle">بطاقة بيانات وتفاصيل المنشط العلمي المعتمد</span>
                </div>
                <button class="close-sidebar-btn" id="closeActivityModalBtn"><i data-lucide="x"></i></button>
            </div>
            <div class="modal-body">

                <div class="meta-tiles">
                    <div class="meta-tile">
                        <i data-lucide="layers"></i>
                        <div class="meta-tile-content">
                            <span class="meta-tile-label">نوع وتصنيف الملتقى</span>
                            <span class="meta-tile-value" id="modalActivityType">--</span>
                        </div>
                    </div>
                    <div class="meta-tile">
                        <i data-lucide="landmark"></i>
                        <div class="meta-tile-content">
                            <span class="meta-tile-label">المكتب الإداري المشرف</span>
                            <span class="meta-tile-value" id="modalOffice">--</span>
                        </div>
                    </div>
                    <div class="meta-tile">
                        <i data-lucide="calendar-check"></i>
                        <div class="meta-tile-content">
                            <span class="meta-tile-label">تاريخ الموعد والإقامة</span>
                            <span class="meta-tile-value" id="modalDate">--</span>
                        </div>
                    </div>
                </div>

                <div id="modalGroupPreachersSection" style="display:none;">
                    <div class="section-divider">
                        <i data-lucide="book-open"></i>
                        <span>برنامج المشائخ الفضلاء وعناوين دروسهم العلمية</span>
                    </div>
                    <table class="speakers-table">
                        <thead>
                            <tr>
                                <th><i data-lucide="user" style="width:14px;height:14px;vertical-align:-2px;"></i> فضيلة الشيخ المحاضر</th>
                                <th>عنوان الدرس / المحاضرة الموكلة إليه</th>
                                <th>وقت المحاضرة</th>
                                <th>مدة المحاضرة</th>
                            </tr>
                        </thead>
                        <tbody id="modalPreachersTableBody"></tbody>
                    </table>
                </div>

                <div>
                    <div class="section-divider">
                        <i data-lucide="map-pin"></i>
                        <span>بيان خط السير ومسار التحرك بالتفصيل</span>
                    </div>
                    <div class="route-box" id="modalRoute">--</div>
                </div>

                <div class="interest-box" id="modalAreYouSection">
                    <div class="interest-box-title"><i data-lucide="help-circle"></i> هل أنت مهتم بهذا الحدث؟</div>
                    <div class="are-you-options-box" id="areYouOptionsBox"></div>
                    <div id="areYouFeedback" class="are-you-feedback hidden"></div>
                </div>
            </div>
            <div class="modal-footer-actions">
                <div id="locationContainer"></div>
                <button class="btn btn-secondary" id="closeActivityModalBtn2">إغلاق النافذة</button>
            </div>
        </div>
    </div>
</div>

<script>
var areYouOptions = {{ are_you_options | tojson }};
var MAP_PAGE_ROUTE = "activity-location";

document.addEventListener('DOMContentLoaded', function () {
    lucide.createIcons();

    /* ================= Main Sidebar ================= */
    var mainSidebar = document.getElementById('mainSidebar');
    var sidebarBackdrop = document.getElementById('sidebarBackdrop');
    var openMainSidebarBtn = document.getElementById('openMainSidebar');
    var closeMainSidebarBtn = document.getElementById('closeMainSidebar');

    function toggleMainSidebar(open) {
        if (open) { mainSidebar.classList.add('open'); sidebarBackdrop.classList.add('active'); }
        else { mainSidebar.classList.remove('open'); sidebarBackdrop.classList.remove('active'); }
    }
    if (openMainSidebarBtn) openMainSidebarBtn.addEventListener('click', function () { toggleMainSidebar(true); });
    if (closeMainSidebarBtn) closeMainSidebarBtn.addEventListener('click', function () { toggleMainSidebar(false); });
    if (sidebarBackdrop) sidebarBackdrop.addEventListener('click', function () { toggleMainSidebar(false); });

    /* ================= Advanced Filter Panel ================= */
    var filterPanel = document.getElementById('filterPanel');
    var filterPanelOverlay = document.getElementById('filterPanelOverlay');
    var openFilterBtn = document.getElementById('openFilterPanelBtn');
    var closeFilterBtn = document.getElementById('closeFilterPanelBtn');

    function toggleFilterPanel(open) {
        if (open) { filterPanel.classList.add('open'); filterPanelOverlay.classList.add('open'); }
        else { filterPanel.classList.remove('open'); filterPanelOverlay.classList.remove('open'); }
    }
    if (openFilterBtn) openFilterBtn.addEventListener('click', function () { toggleFilterPanel(true); });
    if (closeFilterBtn) closeFilterBtn.addEventListener('click', function () { toggleFilterPanel(false); });
    if (filterPanelOverlay) filterPanelOverlay.addEventListener('click', function () { toggleFilterPanel(false); });

    /* ================= Autocomplete & Filtering ================= */
    var cards = document.querySelectorAll('.activity-card');

    function extractUniqueValues(attributeName) {
        var values = new Set();
        cards.forEach(function (card) {
            var val = card.getAttribute(attributeName);
            if (val) {
                if (attributeName === 'data-preacher') {
                    val.split(' ، ').forEach(function (p) { if (p.trim()) values.add(p.trim()); });
                } else {
                    if (val.trim()) values.add(val.trim());
                }
            }
        });
        return Array.from(values);
    }

    var dataset = {
        preacher: extractUniqueValues('data-preacher'),
        aspect: extractUniqueValues('data-aspect'),
        title: extractUniqueValues('data-title'),
        type: extractUniqueValues('data-type'),
        office: extractUniqueValues('data-office')
    };

    function setupAutocomplete(inputId, suggestionsId, dataArray) {
        var input = document.getElementById(inputId);
        var suggestionsContainer = document.getElementById(suggestionsId);
        if (!input || !suggestionsContainer) return;

        input.addEventListener('input', function () {
            var text = this.value.trim();
            suggestionsContainer.innerHTML = '';
            if (!text) { suggestionsContainer.style.display = 'none'; filterActivities(); return; }
            var regex = new RegExp('(' + text.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&') + ')', 'gi');
            var matches = dataArray.filter(function (item) { return item.toLowerCase().includes(text.toLowerCase()); });
            if (matches.length > 0) {
                suggestionsContainer.style.display = 'block';
                matches.forEach(function (match) {
                    var div = document.createElement('div');
                    div.className = 'suggestion-item';
                    div.innerHTML = match.replace(regex, '<span class="suggestion-highlight">$1</span>');
                    div.addEventListener('click', function () { input.value = match; suggestionsContainer.style.display = 'none'; filterActivities(); });
                    suggestionsContainer.appendChild(div);
                });
            } else { suggestionsContainer.style.display = 'none'; }
            filterActivities();
        });
        document.addEventListener('click', function (e) { if (e.target !== input && e.target !== suggestionsContainer) { suggestionsContainer.style.display = 'none'; } });
    }
    setupAutocomplete('searchByPreacher', 'preacherSuggestions', dataset.preacher);
    setupAutocomplete('searchByAspect', 'aspectSuggestions', dataset.aspect);
    setupAutocomplete('searchByTitle', 'titleSuggestions', dataset.title);
    setupAutocomplete('searchByType', 'typeSuggestions', dataset.type);
    setupAutocomplete('searchByOffice', 'officeSuggestions', dataset.office);

    /* ================= Quick Filters (by type) ================= */
    var quickFiltersContainer = document.getElementById('quickFilters');
    var searchByTypeInput = document.getElementById('searchByType');
    if (quickFiltersContainer && dataset.type.length > 0) {
        var allBtn = document.createElement('button');
        allBtn.type = 'button';
        allBtn.className = 'quick-filter-btn active';
        allBtn.setAttribute('data-quick-type', '');
        allBtn.innerText = 'الكل';
        quickFiltersContainer.appendChild(allBtn);

        dataset.type.forEach(function (typeVal) {
            var btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'quick-filter-btn';
            btn.setAttribute('data-quick-type', typeVal);
            btn.innerText = typeVal;
            quickFiltersContainer.appendChild(btn);
        });

        quickFiltersContainer.addEventListener('click', function (e) {
            var btn = e.target.closest('.quick-filter-btn');
            if (!btn) return;
            quickFiltersContainer.querySelectorAll('.quick-filter-btn').forEach(function (b) { b.classList.remove('active'); });
            btn.classList.add('active');
            var typeVal = btn.getAttribute('data-quick-type');
            searchByTypeInput.value = typeVal;
            filterActivities();
        });
    }

    var searchDate = document.getElementById('searchByDate');
    if (searchDate) searchDate.addEventListener('input', filterActivities);

    function filterActivities() {
        var pVal = document.getElementById('searchByPreacher').value.trim().toLowerCase();
        var aVal = document.getElementById('searchByAspect').value.trim().toLowerCase();
        var tVal = document.getElementById('searchByTitle').value.trim().toLowerCase();
        var tyVal = document.getElementById('searchByType').value.trim().toLowerCase();
        var oVal = document.getElementById('searchByOffice').value.trim().toLowerCase();
        var dVal = searchDate ? searchDate.value.trim() : "";
        cards.forEach(function (card) {
            var cPreacher = card.getAttribute('data-preacher').toLowerCase();
            var cAspect = card.getAttribute('data-aspect').toLowerCase();
            var cTitle = card.getAttribute('data-title').toLowerCase();
            var cType = card.getAttribute('data-type').toLowerCase();
            var cOffice = card.getAttribute('data-office').toLowerCase();
            var cDate = card.getAttribute('data-date');
            var matchPreacher = pVal === "" || cPreacher.includes(pVal);
            var matchAspect = aVal === "" || cAspect.includes(aVal);
            var matchTitle = tVal === "" || cTitle.includes(tVal);
            var matchType = tyVal === "" || cType.includes(tyVal);
            var matchOffice = oVal === "" || cOffice.includes(oVal);
            var matchDate = dVal === "" || cDate === dVal;
            if (matchPreacher && matchAspect && matchTitle && matchType && matchOffice && matchDate) { card.style.display = 'flex'; }
            else { card.style.display = 'none'; }
        });
    }

    var resetBtn = document.getElementById('resetFiltersBtn');
    if (resetBtn) {
        resetBtn.addEventListener('click', function () {
            document.querySelectorAll('.autocomplete-input').forEach(function (inp) { inp.value = ""; });
            if (searchDate) searchDate.value = "";
            document.querySelectorAll('.autocomplete-suggestions').forEach(function (box) { box.style.display = 'none'; });
            if (quickFiltersContainer) {
                quickFiltersContainer.querySelectorAll('.quick-filter-btn').forEach(function (b) { b.classList.remove('active'); });
                var allQuickBtn = quickFiltersContainer.querySelector('[data-quick-type=""]');
                if (allQuickBtn) allQuickBtn.classList.add('active');
            }
            filterActivities();
        });
    }

    /* ================= Are-You-Interested (Frappe API) ================= */
    function parseCountsText(raw) {
        var counts = {};
        if (!raw) return counts;
        raw.split('\n').forEach(function (line) {
            var idx = line.indexOf(':');
            if (idx > -1) {
                var key = line.substring(0, idx).trim();
                var val = parseInt(line.substring(idx + 1).trim(), 10);
                if (key && !isNaN(val)) counts[key] = val;
            }
        });
        return counts;
    }
    function buildCountsText(counts) {
        return areYouOptions.map(function (opt) {
            var o = opt.trim();
            return o + ': ' + (counts[o] || 0);
        }).join('\n');
    }
    function lockAreYouButtons(container, selectedValue) {
        Array.from(container.children).forEach(function (btn) {
            btn.classList.add('locked');
            btn.classList.toggle('selected', btn.getAttribute('data-opt') === selectedValue);
        });
    }
    function submitAreYouAnswer(docname, value, container, feedbackEl, voteKey) {
        var getUrl = '/api/method/frappe.client.get_value?doctype=active_taq&filters='
            + encodeURIComponent(JSON.stringify({ name: docname }))
            + '&fieldname=' + encodeURIComponent(JSON.stringify(["are_you_counts"]));

        fetch(getUrl, { headers: { 'X-Frappe-CSRF-Token': (window.frappe && frappe.csrf_token) ? frappe.csrf_token : '' } })
            .then(function (res) { return res.json(); })
            .then(function (res) {
                var raw = (res && res.message && res.message.are_you_counts) || '';
                var counts = parseCountsText(raw);
                counts[value] = (counts[value] || 0) + 1;
                var newText = buildCountsText(counts);

                return fetch('/api/method/frappe.client.set_value', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Frappe-CSRF-Token': (window.frappe && frappe.csrf_token) ? frappe.csrf_token : ''
                    },
                    body: JSON.stringify({
                        doctype: 'active_taq',
                        name: docname,
                        fieldname: 'are_you_counts',
                        value: newText
                    })
                }).then(function (res2) { return res2.json(); }).then(function (data) {
                    if (data && data.exc) { throw new Error(data.exc); }
                    localStorage.setItem(voteKey, value);
                    lockAreYouButtons(container, value);
                    feedbackEl.classList.remove('hidden', 'failed');
                    feedbackEl.innerHTML = '<i data-lucide="check-circle"></i> شكراً لمشاركتك، تم تسجيل إجابتك.';
                    lucide.createIcons();
                });
            }).catch(function () {
                feedbackEl.classList.remove('hidden');
                feedbackEl.classList.add('failed');
                feedbackEl.innerHTML = '<i data-lucide="x-circle"></i> تعذر حفظ إجابتك، تأكد من إعدادات النظام والصلاحيات.';
                lucide.createIcons();
            });
    }

    /* ================= Activity Modal ================= */
    var activityModal = document.getElementById('activityModal');
    var closeActivityModalBtn = document.getElementById('closeActivityModalBtn');
    var closeActivityModalBtn2 = document.getElementById('closeActivityModalBtn2');

    function closeActivityModal() { activityModal.classList.remove('active'); }
    if (closeActivityModalBtn) closeActivityModalBtn.addEventListener('click', closeActivityModal);
    if (closeActivityModalBtn2) closeActivityModalBtn2.addEventListener('click', closeActivityModal);
    activityModal.addEventListener('click', function (e) { if (e.target === activityModal) closeActivityModal(); });

    document.querySelectorAll('.btn-details').forEach(function (button) {
        button.addEventListener('click', function () {
            var title = button.getAttribute('data-title');
            var type = button.getAttribute('data-type');
            var office = button.getAttribute('data-office');
            var date = button.getAttribute('data-date');
            var route = button.getAttribute('data-route');
            var activityId = button.getAttribute('data-activity-id');
            var preachersRaw = button.getAttribute('data-preachers-json');
            var preachersData = [];
            try { preachersData = preachersRaw ? JSON.parse(preachersRaw) : []; } catch (e) { preachersData = []; }

            document.getElementById('modalActivityTitle').innerText = title;
            document.getElementById('modalActivityType').innerText = type;
            document.getElementById('modalOffice').innerText = office;
            document.getElementById('modalDate').innerText = date;
            document.getElementById('modalRoute').innerText = route;

            var tableSection = document.getElementById('modalGroupPreachersSection');
            var tableBody = document.getElementById('modalPreachersTableBody');
            tableBody.innerHTML = '';
            if (preachersData && preachersData.length > 0) {
                tableSection.style.display = 'block';
                preachersData.forEach(function (item) {
                    var row = document.createElement('tr');
                    row.innerHTML = '<td><strong>' + item.name + '</strong></td>' +
                        '<td>' + item.lesson + '</td>' +
                        '<td>' + (item.lecture_time || '-') + '</td>' +
                        '<td>' + (item.lecture_duration || '-') + '</td>';
                    tableBody.appendChild(row);
                });
            } else { tableSection.style.display = 'none'; }

            var locationContainer = document.getElementById('locationContainer');
            locationContainer.innerHTML = '';
            if (activityId) {
                locationContainer.innerHTML =
                    '<a href="/' + MAP_PAGE_ROUTE + '?id=' + encodeURIComponent(activityId) + '" class="btn-map-link">' +
                    '<i data-lucide="map-pin"></i> الانتقال الجغرافي للموقع</a>';
            }

            var areYouBox = document.getElementById('areYouOptionsBox');
            var feedback = document.getElementById('areYouFeedback');
            areYouBox.innerHTML = '';
            feedback.classList.add('hidden');
            feedback.classList.remove('failed');

            var voteKey = 'sabeel_vote_' + activityId;
            var existingVote = localStorage.getItem(voteKey);

            if (areYouOptions && areYouOptions.length > 0) {
                areYouOptions.forEach(function (opt) {
                    var cleanOpt = opt.trim();
                    var btn = document.createElement('button');
                    btn.type = 'button';
                    btn.className = 'btn-are-you';
                    btn.setAttribute('data-opt', cleanOpt);
                    btn.innerText = cleanOpt;
                    btn.addEventListener('click', function () {
                        submitAreYouAnswer(activityId, cleanOpt, areYouBox, feedback, voteKey);
                    });
                    areYouBox.appendChild(btn);
                });

                if (existingVote) {
                    lockAreYouButtons(areYouBox, existingVote);
                    feedback.classList.remove('hidden', 'failed');
                    feedback.innerHTML = '<i data-lucide="check-circle"></i> لقد سجّلت إجابتك مسبقاً على هذا النشاط.';
                }
            } else {
                areYouBox.innerHTML = '<span style="color: var(--text-muted);">لم يتم تحديد خيارات لهذا السؤال بعد.</span>';
            }

            activityModal.classList.add('active');
            lucide.createIcons();
        });
    });

    lucide.createIcons();
});
</script>

